export type Point = readonly [number, number];
export type ParameterValues = Record<string, number>;

export function dataExtent(
  data: readonly (readonly number[])[],
  invalid: (value: number) => boolean = (value) => !Number.isFinite(value),
): readonly [number, number] | null {
  let low = Infinity;
  let high = -Infinity;

  for (const column of data) {
    for (const value of column) {
      if (invalid(value)) continue;
      if (value < low) low = value;
      if (value > high) high = value;
    }
  }

  return Number.isFinite(low) && Number.isFinite(high) ? [low, high] : null;
}

export interface BinCounts {
  counts: number[];
  low: number;
  high: number;
  binWidth: number;
}

export function binCounts(
  values: readonly number[],
  bins: number,
  domain?: readonly [number, number],
): BinCounts {
  const finite = values.filter(Number.isFinite);
  const binTotal = Number.isFinite(bins) ? Math.floor(bins) : 0;
  if (finite.length === 0 || binTotal <= 0) {
    return { counts: [], low: 0, high: 0, binWidth: 0 };
  }

  const low = domain?.[0] ?? Math.min(...finite);
  const high = domain?.[1] ?? Math.max(...finite);
  const binWidth = (high - low || 1) / binTotal;
  const counts = Array.from({ length: binTotal }, () => 0);

  for (const value of finite) {
    let index = Math.floor((value - low) / binWidth);
    if (value === high) index = binTotal - 1;
    if (index >= 0 && index < binTotal) counts[index]++;
  }

  return { counts, low, high, binWidth };
}

export function sampleFunction(
  fn: (x: number, parameters: Readonly<ParameterValues>) => number,
  domain: readonly [number, number],
  parameters: Readonly<ParameterValues> = {},
  samples = 400,
): Point[] {
  const count = Number.isFinite(samples)
    ? Math.max(2, Math.floor(samples))
    : 400;
  const [start, end] = domain;

  return Array.from({ length: count }, (_, index) => {
    const x = start + (index / (count - 1)) * (end - start);
    try {
      const y = fn(x, parameters);
      return [x, Number.isFinite(y) ? y : Number.NaN] as const;
    } catch {
      return [x, Number.NaN] as const;
    }
  });
}

"use client";

import * as React from "react";
import { cn } from "cn";
import { Slider } from "@/components/ui/slider";

export function PlotControls({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      {...props}
      data-slot="plot-controls"
      className={cn("grid w-full min-w-0 gap-5", className)}
    />
  );
}

export interface PlotSliderProps {
  label: React.ReactNode;
  value: number;
  onValueChange: (value: number) => void;
  min: number;
  max: number;
  step?: number;
  formatValue?: (value: number) => string;
  id?: string;
  className?: string;
  disabled?: boolean;
}

export function PlotSlider({
  label,
  value,
  onValueChange,
  min,
  max,
  step,
  formatValue = String,
  id,
  className,
  disabled,
}: PlotSliderProps) {
  const generatedId = React.useId();
  const inputId = id ?? generatedId;
  const labelId = `${inputId}-label`;
  const outputId = `${inputId}-value`;
  return (
    <div className={cn("grid min-w-0 gap-3", className)}>
      <div className="flex items-baseline justify-between gap-4">
        <label id={labelId} htmlFor={inputId} className="text-sm">
          {label}
        </label>
        <output
          id={outputId}
          htmlFor={inputId}
          className="rounded-md bg-muted px-2 py-0.5 font-mono text-xs tabular-nums text-foreground"
        >
          {formatValue(value)}
        </output>
      </div>
      <Slider
        thumbAlignment="center"
        id={inputId}
        aria-labelledby={labelId}
        aria-describedby={outputId}
        value={[value]}
        onValueChange={(next) =>
          onValueChange(Array.isArray(next) ? next[0]! : next)
        }
        min={min}
        max={max}
        step={step ?? (Math.abs(max - min) / 100 || 1)}
        disabled={disabled}
      />
    </div>
  );
}

"use client";

import { ReferenceArea } from "recharts";
import { dataExtent } from "@/registry/plot/lib/data";

export interface PlotHeatmapProps {
  /** Columns of values, with rows increasing along the y domain. */
  data: readonly (readonly number[])[];
  colorScale: (normalized: number) => string;
  domain?: readonly [number, number];
  xDomain: readonly [number, number];
  yDomain: readonly [number, number];
  xAxisId?: string | number;
  yAxisId?: string | number;
  onCellClick?: (column: number, row: number, value: number) => void;
}

/** Numeric grid cells positioned and clipped by the parent Recharts axes. */
export function PlotHeatmap({
  data,
  colorScale,
  domain,
  xDomain: [x0, x1],
  yDomain: [y0, y1],
  xAxisId,
  yAxisId,
  onCellClick,
}: PlotHeatmapProps) {
  const columns = data.length;
  const rows = columns ? Math.max(...data.map((column) => column.length)) : 0;
  const extent = domain ?? dataExtent(data);
  if (!columns || !rows || !extent) return null;
  const [low, high] = extent;
  return data.flatMap((column, col) =>
    column.map((value, row) =>
      Number.isFinite(value) ? (
        <ReferenceArea
          key={`${col}-${row}`}
          xAxisId={xAxisId}
          yAxisId={yAxisId}
          x1={x0 + (col / columns) * (x1 - x0)}
          x2={x0 + ((col + 1) / columns) * (x1 - x0)}
          y1={y0 + (row / rows) * (y1 - y0)}
          y2={y0 + ((row + 1) / rows) * (y1 - y0)}
          fill={colorScale(
            Math.max(0, Math.min(1, (value - low) / (high - low || 1))),
          )}
          fillOpacity={1}
          stroke="none"
          ifOverflow="hidden"
          onClick={onCellClick ? () => onCellClick(col, row, value) : undefined}
        />
      ) : null,
    ),
  );
}

"use client";

import * as React from "react";
import { Line } from "recharts";
import { sampleFunction, type ParameterValues } from "@/registry/plot/lib/data";

export interface PlotFunctionProps extends Omit<
  React.ComponentProps<typeof Line>,
  "data" | "dataKey"
> {
  fn: (x: number, parameters: Readonly<ParameterValues>) => number;
  parameters?: Readonly<ParameterValues>;
  xDomain: readonly [number, number];
  samples?: number;
  /** Return false to leave a gap, for example at a known discontinuity. */
  defined?: (x: number, y: number) => boolean;
}

/** A sampled function rendered by Recharts. Use a numeric XAxis with dataKey="x". */
export function PlotFunction({
  fn,
  parameters,
  xDomain,
  samples = 400,
  defined,
  ...props
}: PlotFunctionProps) {
  const data = sampleFunction(fn, xDomain, parameters, samples).map(
    ([x, y]) => ({
      x,
      y: Number.isFinite(y) && (!defined || defined(x, y)) ? y : null,
    }),
  );
  return (
    <Line
      type="linear"
      dot={false}
      isAnimationActive={false}
      stroke="var(--chart-1)"
      strokeWidth={2}
      {...props}
      data={data}
      dataKey="y"
    />
  );
}

